const res = item.json;
const prev = res.session || {};
const dbg = prev.loginDebug || {};
const rd = res.requestDebug || {};

if (item.error) {
  throw new Error(`Login basarisiz: ${item.error.message || JSON.stringify(item.error)}`);
}

