const hasPanAuth = jarKeys.some((k) => /panauth|\.panauth/i.test(k)) || !!dbg.hasPanAuth;
const loginOk = !!(prev.loginOk || dbg.loginOk || hasPanAuth);

let body = '';
if (typeof res.body === 'string') body = res.body;
else if (typeof res.data === 'string') body = res.data;
else if (res.body != null) body = String(res.body);
else if (res.data != null) body = String(res.data);

const isMac = /Validation of viewstate MAC failed/i.test(body);
const stillOnLogin = !loginOk && (/name=["']edtPass["']/i.test(body) || /name=["']edtUserName["']/i.test(body));

if (isMac) {
  throw new Error(`VIEWSTATE MAC failed. cookies=[${jarKeys.join(',')}]`);
}

if (loginOk) {
  // ok
} else if (stillOnLogin) {
  throw new Error(
    `Login fail (formda kaldi). postStatus=${dbg.postStatus || rd.postStatus} ` +
    `location=${dbg.location || rd.location || ''} hasPanAuth=${hasPanAuth} via=${dbg.via || rd.via || '?'}`
  );
} else if (!hasPanAuth) {
  throw new Error(
    `Login oturum cookie yok (.PanAuth700). keys=[${jarKeys.join(',')}] ` +
    `postStatus=${dbg.postStatus || rd.postStatus} location=${dbg.location || rd.location || ''}`
  );
}

if (!cookieHeader) throw new Error('Login sonrasi cookie yok');

return [{
