function parseSetCookie(headers) {
  const h = headers || {};
  const list = [];
  for (const [k, v] of Object.entries(h)) {
    if (String(k).toLowerCase() !== 'set-cookie') continue;
    if (Array.isArray(v)) list.push(...v);
    else if (v) list.push(v);
  }
  const map = new Map();
  for (const entry of list) {
    if (!entry) continue;
    const chunks = String(entry).split(/,(?=\s*[^;\s=]+=)/);
    for (const chunk of chunks) {
      const nv = chunk.split(';')[0].trim();
      if (!nv || !nv.includes('=')) continue;
      const eq = nv.indexOf('=');
      map.set(nv.slice(0, eq), nv.slice(eq + 1));
    }
  }
  return map;
}

function cookieHeaderFromMap(map) {
  return [...map.entries()].map(([k, v]) => `${k}=${v}`).join('; ');
}

function mergeCookies(jar, headers) {
  for (const [k, v] of parseSetCookie(headers).entries()) jar.set(k, v);
}

function headerGet(headers, name) {
  if (!headers) return '';
  const want = name.toLowerCase();
  for (const [k, v] of Object.entries(headers)) {
    if (String(k).toLowerCase() === want) return Array.isArray(v) ? String(v[0]) : String(v);
  }
  return '';
}

function pickHidden(html, name) {
  const re = new RegExp(
    `name=["']${name}["'][^>]*value=["']([^"']*)["']|value=["']([^"']*)["'][^>]*name=["']${name}["']`,
    'i'
  );
  const m = html.match(re);
  return m ? (m[1] || m[2] || '') : '';
}

function allHiddenInOrder(html) {
  const fields = {};
  const order = [];
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (!/type=["']hidden["']/i.test(tag)) continue;
    const nameM = tag.match(/\bname=["']([^"']+)["']/i);
    if (!nameM) continue;
    const name = nameM[1];
    const valueM = tag.match(/\bvalue=["']([^"']*)["']/i);
    if (!Object.prototype.hasOwnProperty.call(fields, name)) order.push(name);
    fields[name] = valueM ? valueM[1] : '';
  }
  return { fields, order };
}

function encodeForm(fields, order) {
  const keys = order && order.length ? [...order] : Object.keys(fields);
  for (const k of Object.keys(fields)) if (!keys.includes(k)) keys.push(k);
  return keys
    .filter((k) => Object.prototype.hasOwnProperty.call(fields, k))
    .map((k) => {
      const raw = fields[k] == null ? '' : String(fields[k]);
      return encodeURIComponent(k) + '=' + encodeURIComponent(raw).replace(/%20/g, '+');
    })
    .join('&');
}

function resolveFormAction(html, base) {
  const m =
    html.match(/<form[^>]*\bid=["']frmLogin["'][^>]*\baction=["']([^"']*)["']/i) ||
    html.match(/<form[^>]*\bname=["']frmLogin["'][^>]*\baction=["']([^"']*)["']/i) ||
    html.match(/<form[^>]*\baction=["']([^"']*)["'][^>]*\b(?:id|name)=["']frmLogin["']/i);
  let action = m ? m[1] : '/Login.aspx';
  action = action.replace(/&amp;/g, '&');
  if (/^https?:\/\//i.test(action)) return action;
  if (action.startsWith('/')) return base + action;
  return base + '/' + action.replace(/^\.\//, '');
}

async function httpRaw(opts) {
  // 1) legacy request — followRedirect:false guvenilir
  if (this.helpers.request) {
    try {
      const res = await this.helpers.request({
        method: opts.method,
        uri: opts.url,
        headers: opts.headers,
        body: opts.body,
        encoding: 'utf8',
        gzip: true,
        followRedirect: false,
        followAllRedirects: false,
        resolveWithFullResponse: true,
        simple: false,
        timeout: opts.timeout || 60000,
      });
      return {
        statusCode: res.statusCode,
        headers: res.headers || {},
        body: res.body || '',
        via: 'helpers.request',
      };
    } catch (e) {
      // bazi surumlerde 302 exception olabilir
      if (e.statusCode && e.response) {
        return {
          statusCode: e.statusCode,
          headers: (e.response.headers || e.headers || {}),
          body: (e.response.body || e.error || '') + '',
          via: 'helpers.request/error',
        };
      }
      // fall through
    }
  }

  // 2) httpRequest + maxRedirects 0
  const res = await this.helpers.httpRequest({
    method: opts.method,
    url: opts.url,
    headers: opts.headers,
    body: opts.body,
    json: false,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: opts.timeout || 60000,
    maxRedirects: 0,
  });
  let body = res.body;
  if (body != null && typeof body !== 'string') {
    body = Buffer.isBuffer(body) ? body.toString('utf8') : String(body);
  }
  return {
    statusCode: res.statusCode || res.status || 0,
    headers: res.headers || {},
    body: body || '',
    via: 'helpers.httpRequest',
  };
}

