if (item.error || (res.statusCode && res.statusCode >= 400)) {
  throw new Error(`Rapor filtre sayfasi alinamadi (id=${reportId}, HTTP ${res.statusCode || 'n/a'}).`);
}

const html = typeof res.body === 'string'
  ? res.body
  : String(res.body || res.data || '');

if (!html || html.length < 50) {
  throw new Error(`Rapor id=${reportId}: filtre HTML bos.`);
}

if (/edtUserName|edtPass|btnLogin/i.test(html) && !/MainNvg|reportGrid|ExcelAktar/i.test(html)) {
  throw new Error(`Rapor id=${reportId}: filtre yerine login sayfasi dondu. Oturum gecersiz.`);
}

function pickAttr(tag, attr) {
  const key = String(attr).toLowerCase() + '=';
  const lower = tag.toLowerCase();
  let i = lower.indexOf(key);
  while (i !== -1) {
    const q = tag.charAt(i + key.length);
    if (q === '"' || q === "'") {
      const end = tag.indexOf(q, i + key.length + 1);
      if (end !== -1) return tag.slice(i + key.length + 1, end);
    }
    i = lower.indexOf(key, i + 1);
  }
  return '';
}

const fields = {};

const inputRe = /<input\b[^>]*>/gi;
let hm;
while ((hm = inputRe.exec(html)) !== null) {
  const tag = hm[0];
  const type = (pickAttr(tag, 'type') || 'text').toLowerCase();
  const name = pickAttr(tag, 'name');
  if (!name) continue;
  if (type === 'checkbox' || type === 'radio' || type === 'submit' || type === 'image' || type === 'button') continue;
  fields[name] = pickAttr(tag, 'value');
}

const selectRe = /<select\b[^>]*name=["']([^"']+)["'][^>]*>([\s\S]*?)<\/select>/gi;
let sm;
while ((sm = selectRe.exec(html)) !== null) {
  const name = sm[1];
  const inner = sm[2];
  let selected = inner.match(/<option\b[^>]*\bselected\b[^>]*\bvalue=["']([^"']*)["']/i);
  if (!selected) selected = inner.match(/<option\b[^>]*\bvalue=["']([^"']*)["'][^>]*\bselected\b/i);
  if (selected) fields[name] = selected[1];
  else {
    const first = inner.match(/<option\b[^>]*\bvalue=["']([^"']*)["']/i);
    if (first) fields[name] = first[1];
  }
}

const xhrVs = fields['XHRMng$VS'] || '';
const eventValidation = fields.__EVENTVALIDATION || '';
const reqId = fields.__ReqID || '';
const viewState = fields.__VIEWSTATE || '';

if (!xhrVs && !eventValidation) {
  throw new Error(
    `Rapor id=${reportId}: XHRMng$VS / EVENTVALIDATION yok. Sayfa yapisi beklenenden farkli.`
  );
}

if (!/ExcelAktar|MainNvg|reportGrid/i.test(html)) {
  throw new Error(`Rapor id=${reportId}: rapor toolbar/Excel butonu bulunamadi.`);
}

const headers = res.headers || {};
const setCookie = headers['set-cookie'] || headers['Set-Cookie'] || [];
const jar = new Map();
for (const part of (ctx.cookieHeader || '').split(';').map((s) => s.trim()).filter(Boolean)) {
  const eq = part.indexOf('=');
  if (eq > -1) jar.set(part.slice(0, eq), part.slice(eq + 1));
}
for (const c of (Array.isArray(setCookie) ? setCookie : [setCookie]).filter(Boolean)) {
  const part = String(c).split(';')[0].trim();
  const eq = part.indexOf('=');
  if (eq > -1) jar.set(part.slice(0, eq), part.slice(eq + 1));
}
const cookieHeader = [...jar.entries()].map(([k, v]) => `${k}=${v}`).join('; ');

const titleM = html.match(/WebOrtakTitleYaz\(["']([^"']+)["']\)/);

return [{
  json: {
    ...ctx,
    cookieHeader,
    viewState,
    eventValidation,
    reqId,
    xhrVs,
    formFields: fields,
    hasExcelButton: true,
    reportTitleHint: titleM ? titleM[1] : '',
  }
}];

