function pickAttr(tag, attr) {
  const key = String(attr).toLowerCase() + '=';
  const lower = tag.toLowerCase();
  let i = lower.indexOf(key);
  while (i !== -1) {
    const q = tag.charAt(i + key.length);
    if (q === '"' || q === "'") {
      const end = tag.indexOf(q, i + key.length + 1);
      if (end !== -1) return tag.slice(i + key.length + 1, end);
    }
    i = lower.indexOf(key, i + 1);
  }
  return '';
}

