raw = String(raw || '');

const status = res.statusCode || 0;
if (item.error || (status && status >= 400)) {
  const preview = raw.slice(0, 350).replace(/\s+/g, ' ');
  throw new Error(`Excel XHR basarisiz (id=${reportId}, HTTP ${status || 'n/a'}): ${preview}`);
}

if (!raw) {
  throw new Error(`Rapor id=${reportId}: Excel XHR yaniti bos.`);
}

if (/edtUserName|edtPass|btnLogin/i.test(raw) && !/guId|window\.open|Excel|RespJS/i.test(raw)) {
  throw new Error(`Rapor id=${reportId}: Excel XHR oturum dusmus (login HTML).`);
}

let text = raw;
let respJs = [];
try {
  const parsed = JSON.parse(raw);
  if (parsed && Array.isArray(parsed.RespJS)) {
    respJs = parsed.RespJS.map((s) => String(s || ''));
    text = respJs.join('\n');
  } else if (typeof parsed === 'string') {
    text = parsed;
  } else if (parsed && typeof parsed.d === 'string') {
    text = parsed.d;
  } else {
    text = JSON.stringify(parsed);
  }
} catch (_) {}

text = text
  .replace(/\\u0026/g, '&')
  .replace(/\\\//g, '/')
  .replace(/\\"/g, '"')
  .replace(/\\'/g, "'")
  .replace(/&amp;/g, '&');

const patterns = [
  /window\.open\s*\(\s*["']([^"']+)["']/i,
  /window\.open\s*\(\s*`([^`]+)`/i,
  /["'](https?:\/\/[^"']*RaporStream\.aspx[^"']*)["']/i,
  /["'](https?:\/\/[^"']*guId=[^"']+)["']/i,
  /["']([^"']*RaporStream\.aspx[^"']*)["']/i,
  /["']([^"']*Stream\.aspx[^"']*)["']/i,
  /["']([^"']*guId=[^"']+)["']/i,
];

let streamPath = null;
for (const re of patterns) {
  const m = text.match(re);
  if (m && m[1]) {
    streamPath = m[1].trim();
    break;
  }
}

if (!streamPath) {
  const preview = text.slice(0, 400).replace(/\s+/g, ' ');
  throw new Error(
    `Rapor id=${reportId}: stream URL bulunamadi (RespJS bos/yanlis protokol?). Yanit onizleme: ${preview}`
  );
}

const baseUrl = ctx.baseUrl.replace(/\/$/, '');
let streamUrl = streamPath;
if (streamUrl.startsWith('~/')) streamUrl = baseUrl + '/' + streamUrl.slice(2);
else if (streamUrl.startsWith('/')) streamUrl = baseUrl + streamUrl;
else if (!/^https?:\/\//i.test(streamUrl)) streamUrl = baseUrl + '/' + streamUrl;

const headers = res.headers || {};
